from collections import deque


def ancestors(start, parents):
    seen, stack = set(), [start]
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        stack.extend(parents.get(n, []))
    return seen


def merge_base(a, b, parents):
    anc_a = ancestors(a, parents)
    q, seen = deque([b]), set()
    while q:
        n = q.popleft()
        if n in seen:
            continue
        seen.add(n)
        if n in anc_a:
            return n
        q.extend(parents.get(n, []))
    return None


def merge_base_all(a, b, parents):
    anc_a, anc_b = ancestors(a, parents), ancestors(b, parents)
    common = anc_a & anc_b
    children = {c: [n for n, ps in parents.items() if c in ps] for c in parents}
    return sorted(c for c in common if not any(ch in common for ch in children.get(c, [])))


simple = {'X': [], 'A': ['X'], 'B': ['A'], 'C': ['A'], 'M': ['B', 'C']}
print('merge_base(B,C) =', merge_base('B', 'C', simple))
print('merge_base --all (B,C) =', merge_base_all('B', 'C', simple))

criss = {'X': [], 'A': ['X'], 'B': ['X'], 'M1': ['A', 'B'], 'M2': ['A', 'B']}
print('criss-cross merge_base(M1,M2) =', merge_base('M1', 'M2', criss))
print('criss-cross merge_base --all =', merge_base_all('M1', 'M2', criss))

assert merge_base('B', 'C', simple) == 'A'
assert merge_base_all('B', 'C', simple) == ['A']
assert merge_base_all('M1', 'M2', criss) == ['A', 'B']
print('全部断言通过: True')
